 * 页面加载完成后的初始化函数
 * 无论是否有需求代码都必须书写此方法，并放在最前面
 */
function didMount() {
  console.log('多销售订单合并成采购订单功能已加载');
  this.$('button_m4w5glim').set('behavior', 'HIDDEN');
  // 初始化关联销售订单组件的change事件监听
  this.$(ASSOCIATION_FORM_FIELD).on('change', this.handleAssociationFormChange);

  // 初始化生成采购明细按钮的点击事件
  this.$(GENERATE_PURCHASE_BUTTON).on('click', this.handleGeneratePurchaseDetail);
}

/**
 * 关联销售订单变更处理函数
 * 当用户选择多个销售订单时，自动查询并填充销售订单明细
 */
function handleAssociationFormChange() {
  var selectedOrders = this.$(ASSOCIATION_FORM_FIELD).getValue();

  console.log('关联销售订单变更，选中数据:', selectedOrders);

  if (!selectedOrders || selectedOrders.length === 0) {
    // 清空销售订单明细子表
    this.$(SALES_ORDER_DETAIL_TABLE).setValue([]);
    return;
  }

  // 验证选中的订单数据格式
  var validOrders = [];
  for (var i = 0; i < selectedOrders.length; i++) {
    var order = selectedOrders[i];
    if (order && order.instanceId) {
      validOrders.push(order.instanceId);
    } else {
      console.warn('发现无效的订单数据:', order);
    }
  }

  if (validOrders.length === 0) {
    this.utils.toast({
      type: 'warning',
      title: '未找到有效的销售订单'
    });
    return;
  }

  console.log('开始加载 ' + validOrders.length + ' 个销售订单的明细数据');

  // 显示加载中提示
  this.setState({ loading: true });

  // 按顺序处理每个销售订单
  var that = this;
  this.loadSalesOrderDetails(validOrders).then(function () {
    that.utils.toast({
      type: 'success',
      title: '销售订单明细加载完成'
    });
  }).catch(function (error) {
    console.error('加载销售订单明细失败:', error);
    that.utils.toast({
      type: 'error',
      title: '加载销售订单明细失败',
      content: error.message || '请检查网络连接或联系管理员'
    });
  }).finally(function () {
    that.setState({ loading: false });
  });
}

/**
 * 加载销售订单明细数据
 * @param {Array} orderIds - 销售订单ID数组
 * @returns {Promise}
 */
function loadSalesOrderDetails(orderIds) {
  var that = this;
  return new Promise(function (resolve, reject) {
