            for (var key in item) {
              if (item.hasOwnProperty(key)) {
                newItem[key] = item[key];
              }
            }
            newItem[SALES_ORDER_NO_FIELD] = orderData.orderNo;
            newItem._orderIndex = i;
            newItem._itemIndex = j;
            detailsWithOrder.push(newItem);
          }
          allDetails = allDetails.concat(detailsWithOrder);
        }
      }).catch(function (error) {
        console.error('加载订单 ' + orderId + ' 明细失败:', error.message || error);
        // 单个订单失败不影响其他订单的加载
      });
      promises.push(promise);
    }

    Promise.all(promises).then(function () {
      // 按订单顺序和明细顺序排序
      allDetails.sort(function (a, b) {
