        }
        return a._itemIndex - b._itemIndex;
      });

      // 格式化数据并填充到子表
      var formattedDetails = [];
      for (var k = 0; k < allDetails.length; k++) {
        var item = allDetails[k];
        var formattedItem = {};
        formattedItem[SALES_ORDER_NO_FIELD] = item[SALES_ORDER_NO_FIELD];
        formattedItem[SALES_PRODUCT_NAME_FIELD] = item[SALES_PRODUCT_NAME_FIELD] || '';
        formattedItem[SALES_PRODUCT_CODE_FIELD] = item[SALES_PRODUCT_CODE_FIELD] || '';
        formattedItem[SALES_PRODUCT_SPEC_FIELD] = item[SALES_PRODUCT_SPEC_FIELD] || '';
        formattedItem[SALES_BRAND_FIELD] = item[SALES_BRAND_FIELD] || '';
        formattedItem[SALES_QUANTITY_FIELD] = item[SALES_QUANTITY_FIELD] || 0;
        formattedDetails.push(formattedItem);
      }

      that.$(SALES_ORDER_DETAIL_TABLE).setValue(formattedDetails);
      resolve();
    }).catch(reject);
  });
}

/**
 * 获取单个销售订单详情
 * @param {string} orderId - 销售订单实例ID
 * @returns {Promise<Object>}
 */
function getSalesOrderDetail(orderId) {
  var that = this;
  return new Promise(function (resolve, reject) {
    if (!orderId) {
      reject(new Error('订单ID不能为空'));
      return;
    }

    console.log('开始获取订单详情: ' + orderId);

    // 首先获取销售订单主表数据
    that.dataSourceMap.getSalesOrder.load({
      formInstId: orderId,
      appType: APP_TYPE
    }).then(function (orderResult) {
      console.log('销售订单主表数据返回:', orderResult);

      if (!orderResult) {
        var errorMsg = '获取销售订单数据失败';
        console.error('获取销售订单主表数据失败: ' + errorMsg);
        reject(new Error(errorMsg));
        return;
      }

      var orderNo = orderResult.serialNo || orderResult.result.formData[SALES_ORDER_SERIAL_FIELD];

      if (!orderNo) {
        console.error('销售订单编号为空，订单数据:', orderResult.result.formData);
        reject(new Error('获取销售订单编号失败'));
        return;
      }

      // 获取销售订单明细子表数据
      that.dataSourceMap.getSalesOrderDetail.load({
        formUuid: FORM_UUID,
        formInstanceId: orderId,
        tableFieldId: SALES_ORDER_DETAIL_TABLE_SOURCE,
        appType: APP_TYPE,
        pageSize: '50',
        currentPage: '1'
      }).then(function (detailResult) {
        console.log('销售订单明细数据返回:', detailResult);

        if (!detailResult) {
          var errorMsg = '获取销售订单明细失败';
          console.error('获取销售订单明细失败: ' + errorMsg);
          reject(new Error(errorMsg));
          return;
        }

        resolve({
          orderNo: orderNo,
          detailList: detailResult.data || detailResult.result.data || []
        });
      }).catch(function (error) {
        console.error('获取销售订单明细异常:', error);
        reject(new Error('获取销售订单明细异常: ' + (error.message || error)));
      });
    }).catch(function (error) {
      console.error('获取销售订单主表数据异常:', error);
      reject(new Error('获取销售订单主表数据异常: ' + (error.message || error)));
    });
  });
}

