 * 按照产品编码进行合并，数量相加
 * @param {Array} salesDetails - 销售订单明细数据
 * @returns {Array} 合并后的产品列表
 */
function mergeProducts(salesDetails) {
  // 使用普通对象替代Map，避免ES6语法
  var productMap = {};

  for (var i = 0; i < salesDetails.length; i++) {
    var item = salesDetails[i];
    var productCode = item[SALES_PRODUCT_CODE_FIELD];

    if (!productCode) {
      console.warn('发现产品编码为空的数据，跳过合并:', item);
      continue;
    }

    if (productMap.hasOwnProperty(productCode)) {
      // 已存在该产品，合并数量
      var existing = productMap[productCode];
      existing[PURCHASE_QUANTITY_FIELD] += Number(item[SALES_QUANTITY_FIELD]) || 0;
    } else {
      // 新产品，创建新对象
      var purchaseItem = {};
      purchaseItem[PURCHASE_PRODUCT_NAME_FIELD] = item[SALES_PRODUCT_NAME_FIELD] || '';
      purchaseItem[PURCHASE_PRODUCT_CODE_FIELD] = productCode;
      purchaseItem[PURCHASE_PRODUCT_SPEC_FIELD] = item[SALES_PRODUCT_SPEC_FIELD] || '';
      purchaseItem[PURCHASE_BRAND_FIELD] = item[SALES_BRAND_FIELD] || '';
      purchaseItem[PURCHASE_QUANTITY_FIELD] = Number(item[SALES_QUANTITY_FIELD]) || 0;
      // 设置新增状态字段的默认值
      purchaseItem[PURCHASE_RECEIPT_STATUS_FIELD] = DEFAULT_RECEIPT_STATUS;
      purchaseItem[PURCHASE_RECONCILE_STATUS_FIELD] = DEFAULT_RECONCILE_STATUS;
      purchaseItem[PURCHASE_STORAGE_STATUS_FIELD] = DEFAULT_STORAGE_STATUS;
      productMap[productCode] = purchaseItem;
    }
  }

  // 将对象转换为数组
  var result = [];
  for (var code in productMap) {
    if (productMap.hasOwnProperty(code)) {
      result.push(productMap[code]);
    }
  }

  // 排序（按产品编码）
  result.sort(function (a, b) {
    var codeA = a[PURCHASE_PRODUCT_CODE_FIELD];
    var codeB = b[PURCHASE_PRODUCT_CODE_FIELD];
    if (codeA < codeB) return -1;
    if (codeA > codeB) return 1;
    return 0;
  });

  return result;
}

