 *   只写「币别」一个字段，其余字段原值保持不变（深拷贝保证不被触碰）。
 *
 * 表单: 采购订单「流程表单」(FORM-6D7780405CF64AC09936E8AA83121D1AQ3OS)
 * 应用: 新鑫系统 (APP_NVNNBIVSF59IKTEP1L1H)
 *
 * 版本号: v1.0.0
 * 代码类型: formAction
 * 创建时间: 2026-09-21
 * 来源说明: 复用销售订单「币别批量填充」v1.1.0 精简方案，
 *           仅子表ID不同（销售订单 tableField_kk91ezq7 → 采购订单 tableField_kl5u8j5d）
 *
 * 使用说明:
 * 1. 复制本代码到宜搭表单设计器 → 顶部「JS代码」→ 添加文件「1.币别批量填充」
 * 2. 选中主表字段「币别批量填充」→ 右侧属性面板 → 动作 → 值发生变化时
 * 3. 选择函数：onCurrencyBatchFill
 * 4. 保存表单 → 预览测试
 *
 * ⚠️ 关键实现要点:
 * - export function 必须用 function 关键字声明，禁止箭头函数（宜搭运行时无法获取 this）
 * - 子表 setValue 必须带 { triggerChange: false }，否则会触发 onChange 死循环
 * - 子表数据先深拷贝再修改，只改「币别」键，其余字段引用原值不变
 * - 本表单有两个子表（销售订单明细 / 采购明细），币别字段在「采购明细」中
 */

// ===== 配置参数 =====
var CONFIG = {
  // 主表：批量填充来源字段（币别批量填充）
  SOURCE_FIELD: 'selectField_msh9o46w',
  // 子表：采购明细（注意：不是「销售订单明细」tableField_l884dlrk）
  SUB_TABLE: 'tableField_kl5u8j5d',
  // 子表：填充目标字段（币别）— 全代码只写这一个字段
  TARGET_FIELD: 'selectField_mcv84kda'
};

// 全局锁（防止 setValue 触发 onChange 造成重复执行）
var isProcessing = false;

/**
 * 页面加载完成时触发（宜搭表单动作代码必须包含，保留为空）
 * 版本号: v1.0.0
 */
// export function didMount() {
//   console.log('币别批量填充代码已加载，版本号: v1.0.0');
// }

/**
 * 归一化下拉单选字段值
 * SelectField 取值可能是字符串、数组或 {value:...} 对象，统一取第一个有值元素
 * @param {any} value
 * @returns {string}
 */
function normalizeSelectValue(value) {
  if (value === null || value === undefined || value === '') return '';
  if (Array.isArray(value)) {
    if (value.length === 0) return '';
    var first = value[0];
    if (first && (typeof first === 'undefined' ? 'undefined' : _typeof(first)) === 'object') return first.value || '';
    return first;
  }
  if ((typeof value === 'undefined' ? 'undefined' : _typeof(value)) === 'object') return value.value || '';
  return value;
}

/**
 * 币别批量填充（主绑定函数）
 * 绑定位置：主表字段「币别批量填充」(selectField_msh9o46w) → 动作 → 值发生变化时
 * @param {object} event - 事件对象，event.value 为新值
 * 版本号: v1.0.0
 */
function onCurrencyBatchFill(event) {
  if (isProcessing) return;

  try {
    isProcessing = true;

    // 1. 读取「币别批量填充」选中值（优先取组件实时值，event.value 兜底）
    var sourceComponent = this.$(CONFIG.SOURCE_FIELD);
    var rawValue = sourceComponent ? sourceComponent.getValue() : event.value;
    var currencyValue = normalizeSelectValue(rawValue);

    // 2. 值为空：不执行填充，保持子表原样
    if (!currencyValue) {
      console.log('币别批量填充：未选择币种，跳过填充');
      return;
    }

    // 3. 读取「采购明细」子表数据
    var subTableComponent = this.$(CONFIG.SUB_TABLE);
    if (!subTableComponent) {
      console.error('币别批量填充：子表组件不存在，ID:', CONFIG.SUB_TABLE);
      return;
    }

    var rawData = subTableComponent.getValue();
    if (!Array.isArray(rawData) || rawData.length === 0) {
      console.log('币别批量填充：采购明细子表无数据行，跳过填充');
      return;
    }

    // 4. 深拷贝（保证其他字段原值不变），逐行只写「币别」一个字段
    var data;
    try {
      data = JSON.parse(JSON.stringify(rawData));
    } catch (e) {
      data = rawData.slice();
    }

    for (var i = 0; i < data.length; i++) {
      data[i][CONFIG.TARGET_FIELD] = currencyValue;
    }

    // 5. 一次性写回，triggerChange:false 防止 onChange 死循环
    subTableComponent.setValue(data, { triggerChange: false });

    console.log('币别批量填充完成：币种=' + currencyValue + '，已填充行数=' + data.length);
  } catch (error) {
    console.error('币别批量填充错误:', error);
  } finally {
    isProcessing = false;
  }
}

/**
 * ===== 宜搭内配置步骤 =====
 *
 * 【步骤一】添加JS代码
 * 1. 进入「采购订单」表单设计器 → 顶部「JS代码」按钮
 * 2. 点击「添加文件」，文件名填：1.币别批量填充
 * 3. 完整复制粘贴本代码 → 保存
 *
 * 【步骤二】核对字段ID
 * 确认 CONFIG 中三处字段ID与表单实际ID一致：
 * | 用途 | 字段名称 | 字段ID |
 * |------|---------|--------|
 * | 来源字段 | 币别批量填充 | selectField_msh9o46w |
 * | 子表 | 采购明细 | tableField_kl5u8j5d |
 * | 填充目标 | 币别 | selectField_mcv84kda |
 *
 * 【步骤三】绑定事件（必须手动绑定，禁止代码内自动绑定）
 * 1. 在表单设计器中选中主表「币别批量填充」下拉单选组件
 * 2. 右侧属性面板 → 动作 → 值发生变化时
 * 3. 选择函数：onCurrencyBatchFill
 * 4. 保存表单
 *
 * 【步骤四】测试验证
 * 1. 预览表单，先在「采购明细」子表录入若干行产品数据（含产品名称、采购数量等）
 * 2. 在主表「币别批量填充」中选择一个币种（如「人民币」）
 * 3. 预期结果：采购明细子表所有行的「币别」变为所选币种，
 *    其他字段（选择产品、产品名称、采购数量、单价、税率、金额等）保持原值不变
 * 4. 将「币别批量填充」清空为未选择 → 预期：子表币别保持不变，不会被清空
 * 5. 在子表无任何行时选择币种 → 预期：不新增任何行，无任何变化
 *
 * 【常见问题】
 * Q: 选择币种后子表币别没有变化？
 * A: ①确认步骤三已把 onCurrencyBatchFill 绑定到「币别批量填充」的「值发生变化时」；
 *    ②确认 CONFIG.SUB_TABLE 是采购明细 tableField_kl5u8j5d（本表单有两个子表，勿混淆）；
 *    ③浏览器控制台查看是否有「币别批量填充错误」输出
 *
 * Q: 填充后页面卡死或一直在刷新？
 * A: 本代码 setValue 已带 { triggerChange: false }，若仍卡死，
 *    检查是否另有代码在子表 onChange 中调用 setValue 而未加 triggerChange:false
 *
 * 代码版本号: v1.0.0
 */

