/**
 * 多销售订单合并成采购订单功能 - ES5兼容版本
 * 版本号: v1.2.8
 * 创建时间: 2024-12-19
 * 更新日志: 
 *   v1.2.8 - 修复新增状态字段默认值被覆盖问题，在mergeProducts中显式设置默认值
 *   v1.2.7 - 修复pageSize参数超出最大值问题，从100改为50（接口限制最大50）
 *   v1.2.6 - 修复pageSize参数类型问题，将数字改为字符串类型
 *   v1.2.5 - 修复销售订单数据返回结构判断逻辑，适配实际数据结构
 *   v1.2.4 - 修复关联销售订单数据提取逻辑，使用instanceId替代value
 *   v1.2.3 - 完全移除ES6+语法，使用纯ES5语法
 *   v1.2.2 - 修复可选链操作符语法问题
 *   v1.2.1 - 简化代码结构，移除复杂语法
 *   v1.2.0 - 增强错误处理，修复订单数据格式验证问题
 *   v1.1.0 - 将接口参数配置在代码中，数据源面板无需配置参数
 *   v1.0.0 - 初始版本，实现基本功能
 */

// ===== 配置参数定义 =====
// 跨应用数据源配置
var APP_TYPE = 'APP_NVNNBIVSF59IKTEP1L1H';
var FORM_UUID = 'FORM-E865B899BDE445DB82918AE5AC30E34B9D42';

// 当前表单组件ID
var ASSOCIATION_FORM_FIELD = 'associationFormField_l8004daw';
var GENERATE_PURCHASE_BUTTON = 'button_m4w5glim';
var SALES_ORDER_DETAIL_TABLE = 'tableField_l884dlrk';
var PURCHASE_DETAIL_TABLE = 'tableField_kl5u8j5d';

// 销售订单明细子表字段ID
var SALES_ORDER_NO_FIELD = 'textField_l884dlrm';
var SALES_PRODUCT_NAME_FIELD = 'textField_kk91ezq9';
var SALES_PRODUCT_CODE_FIELD = 'textField_kklwpg2y';
var SALES_PRODUCT_SPEC_FIELD = 'textField_kk91ezqa';
var SALES_BRAND_FIELD = 'textField_mcx4vj1u';
var SALES_QUANTITY_FIELD = 'numberField_kkaljjut';

// 采购明细子表字段ID
var PURCHASE_PRODUCT_NAME_FIELD = 'textField_kl5u8j5j';
var PURCHASE_PRODUCT_CODE_FIELD = 'textField_kl5u8j6l';
var PURCHASE_PRODUCT_SPEC_FIELD = 'textField_kl5u8j5l';
var PURCHASE_BRAND_FIELD = 'textField_mho86xpg';
var PURCHASE_QUANTITY_FIELD = 'numberField_l884dlrr';

// 新增状态字段ID
var PURCHASE_RECEIPT_STATUS_FIELD = 'selectField_moij87ds';   // 收票状态字段ID
var PURCHASE_RECONCILE_STATUS_FIELD = 'selectField_moij87dr'; // 对账状态字段ID
var PURCHASE_STORAGE_STATUS_FIELD = 'selectField_moh2f1n6';   // 入库状态字段ID

// 新增状态字段默认值
var DEFAULT_RECEIPT_STATUS = '未收票';
var DEFAULT_RECONCILE_STATUS = '未对账';
var DEFAULT_STORAGE_STATUS = '未入库';

// 销售订单表单字段ID
var SALES_ORDER_SERIAL_FIELD = 'serialNumberField_mhabn0ob';
var SALES_ORDER_DETAIL_TABLE_SOURCE = 'tableField_kk91ezq7';

/**
 * 页面加载完成后的初始化函数
 * 无论是否有需求代码都必须书写此方法，并放在最前面
 */
export function didMount() {
  console.log('多销售订单合并成采购订单功能已加载');
  this.$('button_m4w5glim').set('behavior', 'HIDDEN');
  // 初始化关联销售订单组件的change事件监听
  this.$(ASSOCIATION_FORM_FIELD).on('change', this.handleAssociationFormChange);

  // 初始化生成采购明细按钮的点击事件
  this.$(GENERATE_PURCHASE_BUTTON).on('click', this.handleGeneratePurchaseDetail);
}

/**
 * 关联销售订单变更处理函数
 * 当用户选择多个销售订单时，自动查询并填充销售订单明细
 */
export function handleAssociationFormChange() {
  var selectedOrders = this.$(ASSOCIATION_FORM_FIELD).getValue();

  console.log('关联销售订单变更，选中数据:', selectedOrders);

  if (!selectedOrders || selectedOrders.length === 0) {
    // 清空销售订单明细子表
    this.$(SALES_ORDER_DETAIL_TABLE).setValue([]);
    return;
  }

  // 验证选中的订单数据格式
  var validOrders = [];
  for (var i = 0; i < selectedOrders.length; i++) {
    var order = selectedOrders[i];
    if (order && order.instanceId) {
      validOrders.push(order.instanceId);
    } else {
      console.warn('发现无效的订单数据:', order);
    }
  }

  if (validOrders.length === 0) {
    this.utils.toast({
      type: 'warning',
      title: '未找到有效的销售订单'
    });
    return;
  }

  console.log('开始加载 ' + validOrders.length + ' 个销售订单的明细数据');

  // 显示加载中提示
  this.setState({ loading: true });

  // 按顺序处理每个销售订单
  var that = this;
  this.loadSalesOrderDetails(validOrders)
    .then(function () {
      that.utils.toast({
        type: 'success',
        title: '销售订单明细加载完成'
      });
    })
    .catch(function (error) {
      console.error('加载销售订单明细失败:', error);
      that.utils.toast({
        type: 'error',
        title: '加载销售订单明细失败',
        content: error.message || '请检查网络连接或联系管理员'
      });
    })
    .finally(function () {
      that.setState({ loading: false });
    });
}

/**
 * 加载销售订单明细数据
 * @param {Array} orderIds - 销售订单ID数组
 * @returns {Promise}
 */
export function loadSalesOrderDetails(orderIds) {
  var that = this;
  return new Promise(function (resolve, reject) {
    var allDetails = [];

    // 使用Promise.all并行处理所有订单
    var promises = [];
    for (var i = 0; i < orderIds.length; i++) {
      var orderId = orderIds[i];
      var promise = that.getSalesOrderDetail(orderId)
        .then(function (orderData) {
          if (orderData && orderData.detailList) {
            // 为每个明细项添加订单编号和排序信息
            var detailsWithOrder = [];
            for (var j = 0; j < orderData.detailList.length; j++) {
              var item = orderData.detailList[j];
              var newItem = {};
              // 手动复制属性，避免使用Object.assign
              for (var key in item) {
                if (item.hasOwnProperty(key)) {
                  newItem[key] = item[key];
                }
              }
              newItem[SALES_ORDER_NO_FIELD] = orderData.orderNo;
              newItem._orderIndex = i;
              newItem._itemIndex = j;
              detailsWithOrder.push(newItem);
            }
            allDetails = allDetails.concat(detailsWithOrder);
          }
        })
        .catch(function (error) {
          console.error('加载订单 ' + orderId + ' 明细失败:', error.message || error);
          // 单个订单失败不影响其他订单的加载
        });
      promises.push(promise);
    }

    Promise.all(promises).then(function () {
      // 按订单顺序和明细顺序排序
      allDetails.sort(function (a, b) {
        if (a._orderIndex !== b._orderIndex) {
          return a._orderIndex - b._orderIndex;
        }
        return a._itemIndex - b._itemIndex;
      });

      // 格式化数据并填充到子表
      var formattedDetails = [];
      for (var k = 0; k < allDetails.length; k++) {
        var item = allDetails[k];
        var formattedItem = {};
        formattedItem[SALES_ORDER_NO_FIELD] = item[SALES_ORDER_NO_FIELD];
        formattedItem[SALES_PRODUCT_NAME_FIELD] = item[SALES_PRODUCT_NAME_FIELD] || '';
        formattedItem[SALES_PRODUCT_CODE_FIELD] = item[SALES_PRODUCT_CODE_FIELD] || '';
        formattedItem[SALES_PRODUCT_SPEC_FIELD] = item[SALES_PRODUCT_SPEC_FIELD] || '';
        formattedItem[SALES_BRAND_FIELD] = item[SALES_BRAND_FIELD] || '';
        formattedItem[SALES_QUANTITY_FIELD] = item[SALES_QUANTITY_FIELD] || 0;
        formattedDetails.push(formattedItem);
      }

      that.$(SALES_ORDER_DETAIL_TABLE).setValue(formattedDetails);
      resolve();
    }).catch(reject);
  });
}

/**
 * 获取单个销售订单详情
 * @param {string} orderId - 销售订单实例ID
 * @returns {Promise<Object>}
 */
export function getSalesOrderDetail(orderId) {
  var that = this;
  return new Promise(function (resolve, reject) {
    if (!orderId) {
      reject(new Error('订单ID不能为空'));
      return;
    }

    console.log('开始获取订单详情: ' + orderId);

    // 首先获取销售订单主表数据
    that.dataSourceMap.getSalesOrder.load({
      formInstId: orderId,
      appType: APP_TYPE
    }).then(function (orderResult) {
      console.log('销售订单主表数据返回:', orderResult);

      if (!orderResult) {
        var errorMsg = '获取销售订单数据失败';
        console.error('获取销售订单主表数据失败: ' + errorMsg);
        reject(new Error(errorMsg));
        return;
      }

      var orderNo = orderResult.serialNo || orderResult.result.formData[SALES_ORDER_SERIAL_FIELD];

      if (!orderNo) {
        console.error('销售订单编号为空，订单数据:', orderResult.result.formData);
        reject(new Error('获取销售订单编号失败'));
        return;
      }

      // 获取销售订单明细子表数据
      that.dataSourceMap.getSalesOrderDetail.load({
        formUuid: FORM_UUID,
        formInstanceId: orderId,
        tableFieldId: SALES_ORDER_DETAIL_TABLE_SOURCE,
        appType: APP_TYPE,
        pageSize: '50',
        currentPage: '1'
      }).then(function (detailResult) {
        console.log('销售订单明细数据返回:', detailResult);

        if (!detailResult) {
          var errorMsg = '获取销售订单明细失败';
          console.error('获取销售订单明细失败: ' + errorMsg);
          reject(new Error(errorMsg));
          return;
        }

        resolve({
          orderNo: orderNo,
          detailList: detailResult.data || detailResult.result.data || []
        });
      }).catch(function (error) {
        console.error('获取销售订单明细异常:', error);
        reject(new Error('获取销售订单明细异常: ' + (error.message || error)));
      });
    }).catch(function (error) {
      console.error('获取销售订单主表数据异常:', error);
      reject(new Error('获取销售订单主表数据异常: ' + (error.message || error)));
    });
  });
}

/**
 * 生成采购明细按钮点击处理函数
 * 将销售订单明细中的重复产品合并后填入采购明细子表
 */
export function handleGeneratePurchaseDetail() {
  var salesDetails = this.$(SALES_ORDER_DETAIL_TABLE).getValue();

  if (!salesDetails || salesDetails.length === 0) {
    this.utils.toast({
      type: 'warning',
      title: '请先选择销售订单并加载明细数据'
    });
    return;
  }

  try {
    var mergedProducts = this.mergeProducts(salesDetails);
    this.$(PURCHASE_DETAIL_TABLE).setValue(mergedProducts);

    this.utils.toast({
      type: 'success',
      title: '采购明细生成成功',
      content: '共生成 ' + mergedProducts.length + ' 条采购明细'
    });

  } catch (error) {
    console.error('生成采购明细失败:', error);
    this.utils.toast({
      type: 'error',
      title: '生成采购明细失败',
      content: error.message || '请检查数据格式或联系管理员'
    });
  }
}

/**
 * 合并销售订单明细中的重复产品
 * 按照产品编码进行合并，数量相加
 * @param {Array} salesDetails - 销售订单明细数据
 * @returns {Array} 合并后的产品列表
 */
export function mergeProducts(salesDetails) {
  // 使用普通对象替代Map，避免ES6语法
  var productMap = {};

  for (var i = 0; i < salesDetails.length; i++) {
    var item = salesDetails[i];
    var productCode = item[SALES_PRODUCT_CODE_FIELD];

    if (!productCode) {
      console.warn('发现产品编码为空的数据，跳过合并:', item);
      continue;
    }

    if (productMap.hasOwnProperty(productCode)) {
      // 已存在该产品，合并数量
      var existing = productMap[productCode];
      existing[PURCHASE_QUANTITY_FIELD] += Number(item[SALES_QUANTITY_FIELD]) || 0;
    } else {
      // 新产品，创建新对象
      var purchaseItem = {};
      purchaseItem[PURCHASE_PRODUCT_NAME_FIELD] = item[SALES_PRODUCT_NAME_FIELD] || '';
      purchaseItem[PURCHASE_PRODUCT_CODE_FIELD] = productCode;
      purchaseItem[PURCHASE_PRODUCT_SPEC_FIELD] = item[SALES_PRODUCT_SPEC_FIELD] || '';
      purchaseItem[PURCHASE_BRAND_FIELD] = item[SALES_BRAND_FIELD] || '';
      purchaseItem[PURCHASE_QUANTITY_FIELD] = Number(item[SALES_QUANTITY_FIELD]) || 0;
      // 设置新增状态字段的默认值
      purchaseItem[PURCHASE_RECEIPT_STATUS_FIELD] = DEFAULT_RECEIPT_STATUS;
      purchaseItem[PURCHASE_RECONCILE_STATUS_FIELD] = DEFAULT_RECONCILE_STATUS;
      purchaseItem[PURCHASE_STORAGE_STATUS_FIELD] = DEFAULT_STORAGE_STATUS;
      productMap[productCode] = purchaseItem;
    }
  }

  // 将对象转换为数组
  var result = [];
  for (var code in productMap) {
    if (productMap.hasOwnProperty(code)) {
      result.push(productMap[code]);
    }
  }

  // 排序（按产品编码）
  result.sort(function (a, b) {
    var codeA = a[PURCHASE_PRODUCT_CODE_FIELD];
    var codeB = b[PURCHASE_PRODUCT_CODE_FIELD];
    if (codeA < codeB) return -1;
    if (codeA > codeB) return 1;
    return 0;
  });

  return result;
}

