  // 主表：批量填充来源字段（币别批量填充）
  SOURCE_FIELD: 'selectField_msh9o46w',
  // 子表：采购明细（注意：不是「销售订单明细」tableField_l884dlrk）
  SUB_TABLE: 'tableField_kl5u8j5d',
  // 子表：填充目标字段（币别）— 全代码只写这一个字段
  TARGET_FIELD: 'selectField_mcv84kda'
};

// 全局锁（防止 setValue 触发 onChange 造成重复执行）
var isProcessing = false;

