/**
 * 归一化下拉单选字段值
 * SelectField 取值可能是字符串、数组或 {value:...} 对象，统一取第一个有值元素
 * @param {any} value
 * @returns {string}
 */
function normalizeSelectValue(value) {
  if (value === null || value === undefined || value === '') return '';
  if (Array.isArray(value)) {
    if (value.length === 0) return '';
    var first = value[0];
    if (first && typeof first === 'object') return first.value || '';
    return first;
  }
  if (typeof value === 'object') return value.value || '';
  return value;
}

/**
 * 币别批量填充（主绑定函数）
 * 绑定位置：主表字段「币别批量填充」(selectField_msh9o46w) → 动作 → 值发生变化时
 * @param {object} event - 事件对象，event.value 为新值
 * 版本号: v1.0.0
 */
export function onCurrencyBatchFill(event) {
  if (isProcessing) return;

  try {
    isProcessing = true;

    // 1. 读取「币别批量填充」选中值（优先取组件实时值，event.value 兜底）
    var sourceComponent = this.$(CONFIG.SOURCE_FIELD);
    var rawValue = sourceComponent ? sourceComponent.getValue() : event.value;
    var currencyValue = normalizeSelectValue(rawValue);

    // 2. 值为空：不执行填充，保持子表原样
    if (!currencyValue) {
      console.log('币别批量填充：未选择币种，跳过填充');
      return;
    }

    // 3. 读取「采购明细」子表数据
    var subTableComponent = this.$(CONFIG.SUB_TABLE);
    if (!subTableComponent) {
      console.error('币别批量填充：子表组件不存在，ID:', CONFIG.SUB_TABLE);
      return;
    }

    var rawData = subTableComponent.getValue();
    if (!Array.isArray(rawData) || rawData.length === 0) {
      console.log('币别批量填充：采购明细子表无数据行，跳过填充');
      return;
    }

    // 4. 深拷贝（保证其他字段原值不变），逐行只写「币别」一个字段
    var data;
    try {
      data = JSON.parse(JSON.stringify(rawData));
    } catch (e) {
      data = rawData.slice();
    }

    for (var i = 0; i < data.length; i++) {
      data[i][CONFIG.TARGET_FIELD] = currencyValue;
    }

    // 5. 一次性写回，triggerChange:false 防止 onChange 死循环
    subTableComponent.setValue(data, { triggerChange: false });

    console.log('币别批量填充完成：币种=' + currencyValue + '，已填充行数=' + data.length);
  } catch (error) {
    console.error('币别批量填充错误:', error);
  } finally {
    isProcessing = false;
  }
}

